const event = $json.event || $json.body?.events?.[0] || $json.events?.[0] || $json;
const source = event.source || {};
const message = event.message || {};
const groupId = source.groupId || source.roomId || '';
const isGroup = source.type === 'group' || source.type === 'room';

if (!isGroup || !groupId) {
  return [];
}

return [{
  json: {
    groupId,
    groupName: source.type === 'group' ? '待確認 LINE 群組' : '待確認 LINE Room',
    groupType: '工作群組',
    status: '停用',
    purposes: [],
    lastMessageAt: event.timestamp ? new Date(event.timestamp).toISOString() : new Date().toISOString(),
    lastMessageSummary: message.text || message.type || '非文字訊息',
    lastUserId: source.userId || '',
  },
}];
